from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.pending_signal = None
        self.entry_ticket = None
        self.entry_order_open = False
        self.entry_fill_price = None

        self.held_option = None
        self.exit_ticket = None
        self.exit_order_open = False

        self.block_entries_today = False
        self.last_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime

        # Only use regular-session five-minute bars.
        if end_time.time() < self.TimeRules.GetOpenTime(self.spy).time():
            return

        if end_time.time() > time(16, 0):
            return

        close = float(bar.Close)

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        fast = sum(self.fast_values) / 5.0
        slow = sum(self.slow_values) / 20.0

        if self.previous_fast is not None and self.previous_slow is not None:
            eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

            bullish_cross = (
                self.previous_fast <= self.previous_slow
                and fast > slow
            )

            if eligible_time and bullish_cross:
                self.pending_signal = end_time

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.last_date != current_date:
            self.last_date = current_date
            self.block_entries_today = False

        self.HandleUnexpectedExerciseOrAssignment()

        if self.held_option is not None:
            self.HandleExpirationProtection(slice)
            self.HandleProfitTarget(slice)

        if (
            self.pending_signal is not None
            and self.pending_signal == self.Time
        ):
            self.pending_signal = None

            if (
                not self.block_entries_today
                and self.held_option is None
                and not self.entry_order_open
            ):
                self.TryEnter(slice)

    def TryEnter(self, slice):
        chain = None

        for candidate_chain in slice.OptionChains.Values:
            if candidate_chain.Symbol == self.spy_option.Symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Skipped entry: no current SPY option chain.")
            return

        current_date = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Expiry.date() > current_date
        })

        if not expirations:
            self.Debug("Skipped entry: no valid future expiration.")
            return

        # The specification does not state a DTE target; use the nearest
        # listed future expiration.
        selected_expiration = expirations[0]
        underlying_price = float(self.Securities[self.spy].Price)

        if underlying_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        minimum_strike = underlying_price * 1.01

        candidates = [
            contract
            for contract in chain.Contracts.Values
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Right == OptionRight.Call
                and float(contract.Strike) >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call strike at least 1% above SPY "
                "for the selected expiration."
            )
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))

        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_open = True

        self.Debug(
            f"Submitted SPY call entry: {selected.Symbol}, "
            f"expiration={selected.Expiry.date()}, "
            f"strike={selected.Strike}"
        )

    def HandleProfitTarget(self, slice):
        if (
            self.held_option is None
            or self.exit_order_open
            or self.entry_fill_price is None
        ):
            return

        contract = self.GetHeldContract(slice)

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_fill_price:
            self.CancelOpenExitOrders()

            quantity = self.Portfolio[self.held_option].Quantity
            if quantity > 0:
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -quantity
                )
                self.exit_order_open = True
                self.Debug(
                    f"Profit target reached for {self.held_option}; "
                    f"midpoint={midpoint:.4f}"
                )

    def HandleExpirationProtection(self, slice):
        if self.held_option is None or self.exit_order_open:
            return

        expiration_date = self.held_option.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiration_date:
            self.block_entries_today = True
            self.LiquidateHeldOption("expiration processing")
            return

        preceding_trading_day = self.GetPrecedingTradingDay(expiration_date)

        if (
            current_date == preceding_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.LiquidateHeldOption("expiration time stop")

    def LiquidateHeldOption(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity

        if quantity > 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity
            )
            self.exit_order_open = True
            self.Debug(
                f"Submitted SPY call exit for {self.held_option}: {reason}"
            )

    def GetHeldContract(self, slice):
        if self.held_option is None:
            return None

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol == self.held_option:
                    return contract

        return None

    def CancelOpenExitOrders(self):
        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_ticket.Cancel("Profit target exit supersedes exit")
        self.exit_order_open = False

    def GetPrecedingTradingDay(self, expiration_date):
        candidate = DateTime(
            expiration_date.year,
            expiration_date.month,
            expiration_date.day
        ).AddDays(-1)

        while not self.Securities[self.spy].Exchange.DateIsOpen(candidate):
            candidate = candidate.AddDays(-1)

        return candidate.date()

    def HandleUnexpectedExerciseOrAssignment(self):
        for order_event in self.Transactions.GetOrderEvents():
            if not (
                getattr(order_event, "IsAssignment", False)
                or getattr(order_event, "IsExercise", False)
            ):
                continue

            self.block_entries_today = True
            equity_quantity = self.Portfolio[self.spy].Quantity

            self.Debug(
                f"Unexpected exercise or assignment for "
                f"{order_event.Symbol}; liquidating SPY equity."
            )

            if equity_quantity != 0:
                self.MarketOrder(self.spy, -equity_quantity)

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.entry_order_open = False
                self.held_option = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)

                self.Debug(
                    f"SPY call entry filled: {self.held_option}, "
                    f"fill price={self.entry_fill_price:.4f}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.exit_order_open = False
                self.Debug(
                    f"SPY call exit filled: {order_event.Symbol}, "
                    f"fill price={order_event.FillPrice:.4f}"
                )

                if self.held_option == order_event.Symbol:
                    self.held_option = None
                    self.entry_fill_price = None
                    self.exit_ticket = None

        elif order_event.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.entry_order_open = False
                self.Debug(
                    f"SPY call entry order {order_event.Status}: "
                    f"{order_event.Symbol}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.exit_order_open = False
