from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            True,
            1,
            DataNormalizationMode.Raw,
            False
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-100, 100)
                       .Expiration(0, 365)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.bucket_end = None
        self.bucket_closes = {}

        self.held_option = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_date = None
        self.expiration_day_blocked = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never intentionally carry an option into expiration.
        if self.held_option is not None:
            if self.expiration_date is not None and today >= self.expiration_date:
                self._submit_exit("expiration liquidation")

        # Prevent entries on the expiration date after forced liquidation.
        if self.expiration_date is not None and today >= self.expiration_date:
            self.expiration_day_blocked = today

        # Handle unexpected equity created by exercise or assignment.
        if self.Portfolio[self.spy_symbol].Quantity != 0:
            quantity = self.Portfolio[self.spy_symbol].Quantity
            self.Debug(
                f"{self.Time}: unexpected SPY equity position ({quantity}); liquidating"
            )
            self.MarketOrder(self.spy_symbol, -quantity)
            self.expiration_day_blocked = today

        # Exits are evaluated on every minute Slice.
        self._evaluate_profit_target(slice)
        self._evaluate_time_stop()

        # Build aligned, complete five-minute bars from actual minute bars only.
        if slice.Bars.ContainsKey(self.spy_symbol):
            minute_bar = slice.Bars[self.spy_symbol]
            self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        if not (local_end.hour == 9 and local_end.minute >= 30 or
                10 <= local_end.hour <= 15):
            return

        # A minute bar ending at 09:31 belongs to the five-minute bar
        # ending at 09:35. A bar ending exactly on a boundary closes it.
        remainder = local_end.minute % 5
        minutes_to_boundary = 0 if remainder == 0 else 5 - remainder
        current_end = local_end + timedelta(minutes=minutes_to_boundary)
        current_end = current_end.replace(second=0, microsecond=0)

        if self.bucket_end is not None and current_end != self.bucket_end:
            expected = {
                self.bucket_end - timedelta(minutes=i)
                for i in range(1, 6)
            }

            if set(self.bucket_closes.keys()) == expected:
                closes = [
                    self.bucket_closes[
                        self.bucket_end - timedelta(minutes=i)
                    ]
                    for i in range(5, 0, -1)
                ]
                self._process_five_minute_close(
                    self.bucket_end, closes[-1], slice
                )

            # Missing minute bars invalidate that interval. No filling occurs.
            self.bucket_closes = {}

        self.bucket_end = current_end
        self.bucket_closes[local_end] = float(bar.Close)

        if local_end == current_end and len(self.bucket_closes) == 5:
            expected = {
                current_end - timedelta(minutes=i)
                for i in range(1, 6)
            }
            if set(self.bucket_closes.keys()) == expected:
                closes = [
                    self.bucket_closes[current_end - timedelta(minutes=i)]
                    for i in range(5, 0, -1)
                ]
                self._process_five_minute_close(current_end, closes[-1], slice)
                self.bucket_closes = {}

    def _process_five_minute_close(self, bar_end, close, slice: Slice):
        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        # RollingWindow[0] is current; [1] is the preceding completed bar.
        if self.fast_window.Count < 6 or self.slow_window.Count < 21:
