        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = OrderedDict()

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.expiration_block_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        local_date = self.Time.date()

        # Handle an option that unexpectedly survived until expiration.
        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()

            if local_date >= expiration_date:
                self.expiration_block_date = local_date
                self._submit_exit("expiration processing")

            elif (
                local_date == self._preceding_trading_day(expiration_date)
                and self.Time.hour == 15
                and self.Time.minute == 45
            ):
                self._submit_exit("expiration time stop")

        # Immediately remove unexpected SPY equity created by exercise/assignment.
        if self.Portfolio[self.spy].Quantity != 0:
            if self.equity_liquidation_ticket is None:
                self.Debug(
                    f"{self.Time}: unexpected SPY equity position; liquidating"
                )
                self.equity_liquidation_ticket = self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="Unexpected exercise/assignment liquidation"
                )

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        if self.held_option is None:
            return

        # Profit target is evaluated on every minute Slice.
        quote = self._get_current_option_quote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self._submit_exit("50% profit target")

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        bar_date = bar_time.date()

        # Regular session only; bars are aligned to 09:30 New York time.
        if bar_time.hour < 9 or (
            bar_time.hour == 9 and bar_time.minute < 30
        ):
            return

        if bar_time.hour > 16 or (
            bar_time.hour == 16 and bar_time.minute > 0
        ):
            return

        bucket_start = bar_time.replace(
            hour=9, minute=30, second=0, microsecond=0
        )

        if bar_time < bucket_start:
            return

        elapsed_minutes = int((bar_time - bucket_start).total_seconds() / 60)
        bucket_start += timedelta(minutes=(elapsed_minutes // 5) * 5)

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._complete_bucket(slice)
            self.bucket_bars = OrderedDict()
            self.bucket_start = bucket_start

        self.bucket_bars[bar_time] = bar

        # The last regular-session bar can complete a bucket without a later bar.
        if len(self.bucket_bars) == 5:
            expected = [
                self.bucket_start + timedelta(minutes=i)
                for i in range(5)
            ]

            if list(self.bucket_bars.keys()) == expected:
                self._complete_bucket(slice)

            self.bucket_bars = OrderedDict()
            self.bucket_start += timedelta(minutes=5)

    def _complete_bucket(self, slice: Slice):
        if self.bucket_start is None or len(self.bucket_bars) != 5:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing minute data invalidates the entire five-minute bar.
        if list(self.bucket_bars.keys()) != expected:
            return

        bars = list(self.bucket_bars.values())

        consolidated = TradeBar(
            self.bucket_start,
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.closes.append(float(bar.Close))

