            return

        fast = sum(self.closes[-5:]) / 5.0

        if len(self.closes) < 20:
            return

        slow = sum(self.closes[-20:]) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bar.EndTime

        if not bullish_crossover:
            return

        if not (
            (end_time.hour == 9 and end_time.minute >= 45)
            or (10 <= end_time.hour <= 13)
            or (end_time.hour == 14 and end_time.minute <= 30)
        ):
            return

        if self.held_option is not None or self._entry_order_open():
            return

        if self.expiration_block_date == self.Time.date():
            return

        self._try_enter(slice, float(bar.Close))

    def _try_enter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option_canonical)

        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        today = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() > today
        })

