        bucket_end_minute = 9 * 60 + 30 + ((minutes_from_open + 4) // 5) * 5

        bucket_end = end_time.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._emit_bucket_if_present()

        if self.bucket_end is None:
            self.bucket_end = bucket_end
            self.bucket_open = float(minute_bar.Open)
            self.bucket_high = float(minute_bar.High)
            self.bucket_low = float(minute_bar.Low)
            self.bucket_close = float(minute_bar.Close)
            self.bucket_volume = int(minute_bar.Volume)
        else:
            self.bucket_open = min(self.bucket_open, float(minute_bar.Open))
            self.bucket_high = max(self.bucket_high, float(minute_bar.High))
            self.bucket_low = min(self.bucket_low, float(minute_bar.Low))
            self.bucket_close = float(minute_bar.Close)
            self.bucket_volume += int(minute_bar.Volume)

