        if expiration is None:
            self.Debug("Skipped entry: no valid future expiration.")
            return

        target_strike = 1.01 * self.current_spy_price
        candidates = []

        for contract in chain.Contracts.Values:
            if contract.Right != OptionRight.Call:
                continue

            if contract.Expiry.date() != expiration:
                continue

            if float(contract.Strike) < target_strike:
                continue

            candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"strike={selected.Strike} expiry={selected.Expiry.date()}"
        )

    def _get_current_option_chain(self):
