            return None

        for canonical, chain in self.current_slice.OptionChains.items():
            if canonical == self.option_symbol:
                return chain

        return None

    def _select_expiration(self, chain):
        today = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() > today
        })

        # No explicit DTE range was specified; use the nearest non-expired
        # expiration available in the current Slice.
        return expirations[0] if expirations else None

    def _evaluate_open_position(self, slice):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry:
            self.block_entries_date = today
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry)

        if (
            today == previous_trading_day
            and self.Time.hour * 60 + self.Time.minute >= 15 * 60 + 45
        ):
            self._submit_exit("expiration time stop")
            return

        quote = self._get_current_quote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self._submit_exit("50% profit target")

    def _get_current_quote(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            if symbol not in chain.Contracts:
                continue

            contract = chain.Contracts[symbol]
            return float(contract.BidPrice), float(contract.AskPrice)

        if symbol in slice.QuoteBars:
            quote = slice.QuoteBars[symbol]
            return float(quote.Bid.Close), float(quote.Ask.Close)

        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._is_order_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by liquidation request")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _is_order_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)

                if order_event.Status == OrderStatus.Filled:
                    self.entry_ticket = None

                self.Debug(
                    f"Entry filled: {self.held_symbol} "
                    f"price={self.entry_price}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
                and order_event.Status == OrderStatus.Filled
            ):
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

        if order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.entry_ticket = None

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment detected.")

            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Unexpected exercise/assignment liquidation"
                )
                self.Debug("Liquidated SPY equity from exercise or assignment.")
