        if self.no_reentry_date == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped selection: no option chain")
            return

        # No target DTE was specified, so select the nearest future expiry.
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - self.Time.date()).days > 0
