        if self.IsTicketOpen(self.entry_ticket):
            self.entry_ticket.Cancel("Exit required")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )

        self.Debug(
            "Exit submitted ({}): {}".format(
                reason,
                self.held_option
            )
        )

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[
            self.spy_symbol
        ].Exchange.Hours

        while not exchange_hours.IsDateOpen(
