        ):
            candidate -= timedelta(days=1)

        return candidate

    def LiquidateUnexpectedSpyPosition(self):
        holding = self.Portfolio[self.spy_symbol]

        if (
            holding.Quantity != 0
            and not self.spy_liquidation_submitted
        ):
