from AlgorithmImports import *
from collections import deque
from datetime import timedelta
from System import DateTime


class SpyFiveMinuteCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.entry_order_id = None
        self.held_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.exit_order_id = None

        self.expiration_block_date = None
        self.spy_liquidation_ticket = None
        self.spy_liquidation_order_id = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never intentionally carry an option into its expiration date.
        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if today >= expiry_date:
                self.expiration_block_date = today
                self._submit_option_exit("expiration-day liquidation")
            elif self.Time.hour > 15 or (
                self.Time.hour == 15 and self.Time.minute >= 45
            ):
                previous_trading_day = self._previous_trading_day(expiry_date)
                if today == previous_trading_day:
                    self._submit_option_exit("pre-expiration time stop")

        # Handle any unexpected SPY equity position, including assignment.
        spy_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if spy_quantity != 0:
            self.expiration_block_date = today
            if not self._ticket_is_open(self.spy_liquidation_ticket):
                self.Debug(
                    f"Unexpected SPY equity position detected: "
                    f"{spy_quantity} shares; liquidating."
                )
                self.spy_liquidation_ticket = self.MarketOrder(
                    self.spy.Symbol,
                    -spy_quantity,
                    tag="unexpected exercise or assignment"
                )
                self.spy_liquidation_order_id = (
                    self.spy_liquidation_ticket.OrderId
                )

        # The profit target is evaluated on every minute Slice.
        self._check_profit_target(slice)

        # Build a five-minute bar from actual minute bars only.
        minute_bar = slice.Bars.get(self.spy.Symbol)
        if minute_bar is None:
            return

        completed_bar = self._add_minute_bar(minute_bar)
        if completed_bar is None:
            return

        self._update_averages_and_check_entry(completed_bar, slice)

    def _add_minute_bar(self, minute_bar):
        local_time = minute_bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if not (
            (local_time.hour > 9 or
             (local_time.hour == 9 and local_time.minute >= 30))
            and local_time.hour < 16
        ):
            return None

        minute_of_day = local_time.hour * 60 + local_time.minute
        bucket_minute = (minute_of_day // 5) * 5
        bucket_start = local_time.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60,
            second=0,
            microsecond=0
        )

        if (
            self.current_bucket_start is not None
            and bucket_start != self.current_bucket_start
        ):
            completed = self._complete_bucket()
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = {
                local_time: minute_bar
            }
            return completed

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start

        self.current_bucket_bars[local_time] = minute_bar
        return None

    def _complete_bucket(self):
        if self.current_bucket_start is None:
            return None

        expected_times = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self.current_bucket_bars for t in expected_times):
            self.current_bucket_bars = {}
            return None

        bars = [self.current_bucket_bars[t] for t in expected_times]
        self.current_bucket_bars = {}

        return {
            "end_time": self.current_bucket_start + timedelta(minutes=5),
            "close": bars[-1].Close
        }

    def _update_averages_and_check_entry(self, bar, slice):
        close = float(bar["close"])

        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = sum(self.fast_values) / len(self.fast_values)
        slow = sum(self.slow_values) / len(self.slow_values)

        self.previous_fast = fast
        self.previous_slow = slow

        crossover = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and fast > slow
        )

        end_time = bar["end_time"]
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        eligible_time = (
            (end_time.hour > 9 or
             (end_time.hour == 9 and end_time.minute >= 45))
            and
            (end_time.hour < 14 or
             (end_time.hour == 14 and end_time.minute <= 30))
        )

        if crossover and eligible_time:
            self._try_enter(slice, close)

    def _try_enter(self, slice, spy_price):
        today = self.Time.date()

        if self.expiration_block_date == today:
            return

        if self.held_symbol is not None:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        if self.spy_option.Symbol not in slice.OptionChains:
            self.Debug("Skipped call selection: no option chain in Slice.")
            return

        chain = slice.OptionChains[self.spy_option.Symbol]
        contracts = list(chain.Contracts.values())

        future_contracts = [
            contract for contract in contracts
            if contract.Expiry.date() > today
        ]

        if not future_contracts:
            self.Debug("Skipped call selection: no valid future expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in future_contracts
        )

        strike_floor = 1.01 * float(spy_price)
        candidates = [
            contract for contract in future_contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= strike_floor
        ]

        if not candidates:
            self.Debug(
                "Skipped call selection: no call met the expiration and strike rules."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId

        self.Debug(
            f"Submitted call entry: {selected.Symbol}, "
            f"expiration {selected_expiry}, strike {selected.Strike}."
        )

    def _check_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quote_bar = slice.QuoteBars.get(self.held_symbol)
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = quote_bar.Bid.Close
        ask = quote_bar.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_option_exit("50% profit target")

    def _submit_option_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            if reason == "50% profit target":
                self.exit_ticket.Cancel("profit target superseded prior exit")
            else:
                return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = self.exit_ticket.OrderId

        self.Debug(
            f"Submitted option exit: {self.held_symbol}; reason: {reason}."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Call entry filled: {self.held_symbol}, "
                    f"fill price {self.entry_price:.4f}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_order_id = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"Option position exited: {order_event.Symbol}, "
                f"fill price {order_event.FillPrice:.4f}."
            )
            self.exit_ticket = None
            self.exit_order_id = None
            self.held_symbol = None
            self.entry_price = None

        if (
            getattr(order_event, "IsAssignment", False)
            or getattr(order_event, "IsExercise", False)
        ):
            self.expiration_block_date = self.Time.date()
            self.Debug(
                f"Unexpected exercise or assignment event: "
                f"{order_event.Symbol}."
            )

            spy_quantity = self.Portfolio[self.spy.Symbol].Quantity
            if spy_quantity != 0 and not self._ticket_is_open(
                self.spy_liquidation_ticket
            ):
                self.spy_liquidation_ticket = self.MarketOrder(
                    self.spy.Symbol,
                    -spy_quantity,
                    tag="unexpected exercise or assignment"
                )
                self.spy_liquidation_order_id = (
                    self.spy_liquidation_ticket.OrderId
                )

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            DateTime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate
