        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.group_start = None
        self.minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.no_trade_date = None
        self.last_time_stop_date = None

    def OnData(self, slice: Slice):
        now = self.Time

        # No strategy path intentionally creates SPY equity holdings.
        if self.Portfolio[self.spy_symbol].Invested:
            self.Debug("Unexpected SPY equity position; liquidating")
            self.MarketOrder(
                self.spy_symbol,
                -self.Portfolio[self.spy_symbol].Quantity,
                tag="unexpected exercise/assignment"
            )

        self.CheckExpirationSafety(now)
        self.CheckTimeStop(now)
        self.CheckProfitTarget(slice)

        minute_bar = slice.Bars.get(self.spy_symbol)
        if minute_bar is None:
            return

        completed_bar = self.AddMinuteBar(minute_bar)
        if completed_bar is None:
            return

        self.fast.Update(completed_bar.EndTime, completed_bar.Close)
        self.slow.Update(completed_bar.EndTime, completed_bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_time = completed_bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (
            bullish_crossover and
            eligible_time and
            self.no_trade_date != now.date()
        ):
            self.TryEntry(slice, completed_bar.Close)

    def AddMinuteBar(self, bar):
        end = bar.EndTime.replace(second=0, microsecond=0)

        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return None

        origin = datetime.combine(end.date(), time(9, 30))
        elapsed = end - timedelta(minutes=1) - origin
        bucket_number = int(elapsed.total_seconds() // 300)
        bucket_end = origin + timedelta(minutes=(bucket_number + 1) * 5)

        completed = None

        if self.group_start is not None and bucket_end != self.group_start:
            completed = self.FinishMinuteGroup()
            self.minute_bars = {}

        self.group_start = bucket_end
        self.minute_bars[end] = bar

        return completed

    def FinishMinuteGroup(self):
        if self.group_start is None:
            return None

        expected_times = [
            self.group_start - timedelta(minutes=4) + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing minute data means no five-minute bar is emitted.
        if any(t not in self.minute_bars for t in expected_times):
            return None

        bars = [self.minute_bars[t] for t in expected_times]

        return TradeBar(
            self.group_start - timedelta(minutes=5),
            self.spy_symbol,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

    def TryEntry(self, slice: Slice, underlying_price):
        if self.held_symbol is not None or self.entry_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        today = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= today
        })

        if not expirations:
            self.Debug("Skipped entry: no valid expiration")
            return

        expiration = expirations[0]
        minimum_strike = underlying_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        contract = candidates[0]

        self.entry_ticket = self.MarketOrder(
            contract.Symbol,
            1,
            tag="bullish crossover"
        )

        self.Debug(
            "Entry submitted: {} expiration {} strike {}".format(
                contract.Symbol,
                expiration,
                contract.Strike
            )
        )

    def CheckProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.ExitOrderOpen():
            return

        quote = slice.QuoteBars.get(self.held_symbol)

        if quote is None:
            return

        if quote.Bid is None or quote.Ask is None:
            return

        if quote.Bid <= 0 or quote.Ask <= 0:
            return

        midpoint = (quote.Bid + quote.Ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def CheckTimeStop(self, now):
        if self.held_symbol is None:
            return

        if self.no_trade_date == now.date():
            return

        expiration = self.held_symbol.ID.Date.date()
        preceding_day = expiration - timedelta(days=1)

        if (
            now.date() == preceding_day and
            now.time() >= time(15, 45) and
            self.last_time_stop_date != now.date()
        ):
            self.last_time_stop_date = now.date()
            self.SubmitExit("pre-expiration time stop")

    def CheckExpirationSafety(self, now):
        if self.held_symbol is None:
            return

        expiration = self.held_symbol.ID.Date.date()

        if now.date() >= expiration:
            self.no_trade_date = now.date()
            self.SubmitExit("expiration safety liquidation")

    def ExitOrderOpen(self):
        return (
            self.exit_ticket is not None and
            self.exit_ticket.Status not in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ]
        )

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.ExitOrderOpen():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("replaced by " + reason)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {} ({})".format(
                self.held_symbol,
                reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if (
                order_event.Status == OrderStatus.Filled and
                self.entry_price is None
            ):
                self.entry_price = order_event.FillPrice
                self.held_symbol = order_event.Symbol

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            "Unexpected exercise/assignment; liquidating SPY equity"
        )

        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity != 0:
            self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="unexpected assignment"
            )

