from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    TARGET_DTE = 30

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY", Resolution.Minute, Market.USA, False, 0, True
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                        .Strikes(-200, 200)
                        .Expiration(0, 365)
        )

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None
        self.buckets = {}

        self.entry_ticket = None
        self.entry_order_id = None
        self.exit_ticket = None
        self.exit_order_id = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.no_entry_today = False
        self.last_date = None
        self.expiration_processed = None

    def OnData(self, slice: Slice):
        now = self.Time

        if self.last_date != now.date():
            self.last_date = now.date()
            self.no_entry_today = False

        if self.Portfolio[self.spy.Symbol].Invested:
            quantity = self.Portfolio[self.spy.Symbol].Quantity
            self.Debug("Unexpected SPY exercise/assignment; liquidating equity")
            self.MarketOrder(self.spy.Symbol, -quantity)
            self.no_entry_today = True

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if now.date() >= expiry:
                if self.expiration_processed != now.date():
                    self.Debug("Unexpected expiration holding; liquidating option")
                    self._submit_exit("expiration")
                    self.expiration_processed = now.date()
                self.no_entry_today = True

        self._evaluate_time_stop()
        self._evaluate_profit_target(slice)

        bar = slice.Bars.get(self.spy.Symbol)
        if bar is None:
            return

        consolidated = self._consolidate_minute(bar)
        if consolidated is None:
            return

        end_time, close = consolidated
        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        fast = sum(self.closes[-5:]) / 5.0
        slow = sum(self.closes[-20:]) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish:
            return

        if not (
            datetime.strptime("09:45", "%H:%M").time()
            <= end_time.time()
            <= datetime.strptime("14:30", "%H:%M").time()
        ):
            return

        if (
            self.no_entry_today
            or self.held_symbol is not None
            or self._entry_is_open()
        ):
            return

        self._try_enter(slice)

    def _consolidate_minute(self, bar):
        now = self.Time

        if now.time() < datetime.strptime("09:30", "%H:%M").time():
            return None

        if now.time() > datetime.strptime("16:00", "%H:%M").time():
            return None

        end_minute = now.hour * 60 + now.minute
        bucket_start = 570 + ((end_minute - 575) // 5) * 5
        key = (now.date(), bucket_start)

        self.buckets.setdefault(key, {})[end_minute] = bar

        complete_keys = [
            k for k, values in self.buckets.items()
            if k[0] == now.date()
            and k[1] <= bucket_start
            and len(values) == 5
        ]

        if not complete_keys:
            return None

        completed_key = max(complete_keys, key=lambda x: x[1])
        values = self.buckets.pop(completed_key)

        expected = set(range(completed_key[1] + 1, completed_key[1] + 6))
        if set(values.keys()) != expected:
            return None

        bars = [values[m] for m in sorted(values)]
        end = datetime.combine(
            now.date(),
            datetime.min.time()
        ) + timedelta(minutes=completed_key[1] + 5)

        return end, bars[-1].Close

    def _try_enter(self, slice: Slice):
        chain = slice.OptionChains.get(self.option.Symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        spy_price = float(self.Securities[self.spy.Symbol].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        target_expiry = self.Time.date() + timedelta(days=self.TARGET_DTE)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() == target_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: target expiration unavailable")
            return

        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expirations[0]
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled at " + str(self.entry_fill_price)
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self.exit_ticket = None
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_fill_price = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected exercise/assignment event")
            quantity = self.Portfolio[self.spy.Symbol].Quantity
            if quantity != 0:
                self.MarketOrder(self.spy.Symbol, -quantity)
            self.no_entry_today = True

    def _entry_is_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _exit_is_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if (
            self.held_symbol is None
            or self.entry_fill_price is None
            or self._exit_is_open()
        ):
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (c for c in chain if c.Symbol == self.held_symbol),
            None
        )

        if contract is None:
            return

        if contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0

        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("profit target")

    def _evaluate_time_stop(self):
        if self.held_symbol is None or self._exit_is_open():
            return

        expiry = self.held_symbol.ID.Date.date()
        candidate = expiry - timedelta(days=1)

        while (
            candidate.weekday() >= 5
            or not self.Securities[self.spy.Symbol]
                .Exchange.Hours.IsDateOpen(candidate)
        ):
            candidate -= timedelta(days=1)

        if (
            self.Time.date() == candidate
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None or self._exit_is_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug(
            "Exit submitted (" + reason + "): "
            + str(self.held_symbol)
        )

